function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}
const sections = plain(Inputs.sections) || [];
const steps = plain(Inputs.steps) || [];
if (!steps.length || !sections.length) return;
let index = steps.findIndex((s) => s.id === Inputs.activeStepId);
if (index < 0) index = 0;
const step = steps[index];
const byId = new Map(sections.map((s) => [s.id, s]));
// THE STRINGS RIDE THE ROW (TASK-L160). A For Each maps an item's properties
// onto the template component's inputs BY NAME, so `copy` on the row is what
// fills Section row's Copy input and reaches the kit node. It is one object by
// reference on every row, never 80 string parameters. Undefined is a supported
// value: the kit then renders the English it ships (L160 AC1).
const copy = plain(Inputs.copy) || undefined;
const rows = (step.sectionIds || []).map((id) => {
  const section = byId.get(id);
  if (!section) throw new Error('step "' + step.id + '" claims section "' + id + '", which this lesson does not have');
  return { id: id, section: section, copy: copy };
});
Outputs.rows = rows;
Outputs.count = rows.length;
// A built-in Button paints its background and colour INLINE, so a class alone
// cannot switch the active chip: the two colours ride the row data as tokens.
Outputs.chips = steps.map((s, i) => ({
  id: s.id,
  title: s.title,
  index: i,
  active: i === index,
  className: i === index ? 'lesson-step-chip dbt-chip active' : 'lesson-step-chip dbt-chip',
  bg: i === index ? 'var(--primary)' : 'var(--surface-raised)',
  fg: i === index ? 'var(--primary-foreground)' : 'var(--muted-foreground)'
}));
Outputs.stepTitle = step.title || '';
Outputs.stepGoal = step.goal || '';
Outputs.unlocks = step.unlocks || '';
const hasNext = index < steps.length - 1;
Outputs.hasNext = hasNext;
Outputs.nextTitle = hasNext ? steps[index + 1].title : '';
Outputs.nextStepId = hasNext ? steps[index + 1].id : '';
Outputs.activeIndex = index;
